CREATE VIEW mart_quality_signal_v1 AS WITH critic_quality AS (SELECT er.GameID, avg(CASE  WHEN ((rt.RatingTypeName IN ('Critic', 'Composite'))) THEN (er.RatingValue) ELSE NULL END) AS avg_quality_rating, count(CASE  WHEN ((rt.RatingTypeName IN ('Critic', 'Composite'))) THEN (1) ELSE NULL END) AS quality_rating_count, count(DISTINCT CASE  WHEN ((rt.RatingTypeName IN ('Critic', 'Composite'))) THEN (er.RatingSourceID) ELSE NULL END) AS quality_source_count FROM ExternalRating AS er INNER JOIN RatingType AS rt ON ((rt.RatingTypeID = er.RatingTypeID)) GROUP BY er.GameID), user_quality AS (SELECT er.GameID, avg(er.RatingValue) AS avg_user_rating, count_star() AS user_rating_count FROM ExternalRating AS er INNER JOIN RatingType AS rt ON ((rt.RatingTypeID = er.RatingTypeID)) WHERE (rt.RatingTypeName = 'User') GROUP BY er.GameID), ranked AS (SELECT dg.GameKey, dg.GameID, dg.GameTitle, cq.avg_quality_rating, cq.quality_rating_count, cq.quality_source_count, uq.avg_user_rating, uq.user_rating_count, CASE  WHEN ((cq.avg_quality_rating IS NOT NULL)) THEN ((percent_rank() OVER (ORDER BY cq.avg_quality_rating) * 100.0)) ELSE NULL END AS quality_percentile FROM DimGame AS dg LEFT JOIN critic_quality AS cq ON ((cq.GameID = dg.GameID)) LEFT JOIN user_quality AS uq ON ((uq.GameID = dg.GameID)))SELECT GameKey, GameID, GameTitle, round(avg_quality_rating, 2) AS avg_quality_rating, quality_rating_count, quality_source_count, round(avg_user_rating, 2) AS avg_user_rating, user_rating_count, round(quality_percentile, 2) AS quality_percentile, CASE  WHEN ((avg_quality_rating IS NULL)) THEN ('No Quality Rating') WHEN ((quality_source_count >= 3)) THEN ('High Coverage') WHEN ((quality_source_count = 2)) THEN ('Moderate Coverage') ELSE 'Low Coverage' END AS quality_coverage_status FROM ranked;
